#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-09-10
/**
 * allowed-tools-check.mjs: a skill's tool list must agree with its own prose.
 *
 * WHAT `allowed-tools` ACTUALLY IS, because getting this wrong changes the fix.
 * Per the Claude Code docs (https://code.claude.com/docs/en/skills.md):
 *
 *   "The allowed-tools field grants permission for the listed tools during the
 *    turn that invokes the skill, so Claude can use them without prompting you
 *    for approval. It does not restrict which tools are available: every tool
 *    remains callable, and your permission settings still govern tools that are
 *    not listed."
 *
 * So for Claude Code it is a PRE-GRANT, not a ceiling. An agent's `tools`
 * frontmatter is a ceiling; a skill's `allowed-tools` is not.
 *
 * That refutes the framing in #4008. A skill whose prose says "Run `npm test`"
 * while listing only read-only tools is NOT "unable to carry out its own
 * instructions" under Claude Code, and it does not silently report work it
 * never did. Three real consequences remain, which is why this gate exists:
 *
 *   1. A missing pre-grant means an approval prompt lands in the middle of the
 *      skill's own procedure. The field's entire purpose is to avoid that, so a
 *      skill that instructs an action and omits its tool is self-defeating.
 *   2. The Cursor host reads `allowed-tools` off the generated command files and
 *      treats it as a ceiling. Same text, stricter reading, real breakage.
 *   3. Prose honesty. A skill that reads as if it performs work it was never
 *      equipped to perform misleads the next author, whatever the runtime does.
 *
 * The gate therefore asserts ONE thing: a skill's declared tool list and its own
 * instructions agree. That is true or false on the file alone, with no runtime
 * measurement behind it, so it stays correct if upstream semantics change again.
 *
 * PRECISION OVER RECALL, on purpose. Only IMPERATIVE INSTRUCTION LINES count:
 * "Run `npm test`", "Create `src/x.ts`", "Ask the user". A fenced ```bash block
 * is NOT counted, because a pattern skill quoting a command is teaching, not
 * instructing, and that distinction is the whole judgment call in #4008. A
 * checker that flagged every fenced block would report most of the corpus and be
 * ignored, which is worse than one that reports less and is believed.
 *
 * Two fixes, and which one is right is a per-skill judgment recorded in
 * docs/skills-allowed-tools-direction.md:
 *   - The skill really performs the work -> LIST the tool. That is what removes
 *     the prompt, which is the whole point of the field.
 *   - The skill only teaches -> keep the read-only list and reword the step as
 *     advice rather than an action it performs.
 *
 * Ratchet: every skill in allowed-tools-baseline.json is grandfathered. The gate
 * fails on a NEW offender, and on a baseline entry that no longer offends
 * (delete it; the list only shrinks). Same shape as fh-ready-check.mjs.
 */
import { readFileSync, readdirSync, existsSync, statSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, '..');
const SKILLS_ROOT = join(REPO_ROOT, 'src', 'skills');
const BASELINE_PATH = join(__dirname, 'allowed-tools-baseline.json');

/**
 * Imperative instruction patterns, each mapped to the tool it requires.
 *
 * Anchored to the start of a line (allowing list and numbered-list markers) so
 * prose that merely mentions the word does not match. "You can run the suite
 * with npm test" is not an instruction; "Run `npm test`" is.
 */
const REQUIREMENTS = [
  {
    // The backtick must hold something that could be typed at a shell: starts
    // with a word character and is not a bare `fn()` call or a bare `--flag`.
    // Both showed up as false positives on the first run: mcp-patterns quoted
    // the Python `cleanup_expired()` and testing-perf quoted the pytest flag
    // `--lf`. Neither is an instruction to run a shell command, and a checker
    // that reports them stops being believed.
    tool: 'Bash',
    re: /^\s*(?:[-*+]|\d+\.)?\s*(?:Run|Execute|Invoke)\s+(?:the\s+\S+\s+)?`(?!-)[A-Za-z0-9_./-]+(?:\s[^`]*)?`/im,
    label: 'an imperative "Run `<command>`"',
    reject: /^`[A-Za-z0-9_]+\(\)`$/,
  },
  {
    tool: 'Write',
    re: /^\s*(?:[-*+]|\d+\.)?\s*(?:Create|Write|Save|Generate)\s+(?:a\s+|the\s+|new\s+)*`[^`]*\.[A-Za-z0-9]+`/im,
    label: 'an imperative "Create `<file>`"',
  },
  {
    tool: 'Edit',
    re: /^\s*(?:[-*+]|\d+\.)?\s*(?:Edit|Modify|Update)\s+(?:the\s+)?`[^`]*\.[A-Za-z0-9]+`/im,
    label: 'an imperative "Edit `<file>`"',
  },
  {
    tool: 'AskUserQuestion',
    re: /^\s*(?:[-*+]|\d+\.)?\s*Ask\s+the\s+user\b/im,
    label: 'an imperative "Ask the user"',
  },
];

/** Tools that satisfy a requirement even when not named literally. */
const SATISFIES = {
  Write: ['Write', 'Edit'],
  Edit: ['Edit', 'Write'],
  Bash: ['Bash'],
  AskUserQuestion: ['AskUserQuestion'],
};

function parseFrontmatter(text) {
  const m = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text);
  if (!m) return null;
  // Deliberately not a YAML dependency: this reads one scalar-or-list field,
  // and the repo's other gates stay dependency-free for the same reason.
  const body = m[1];
  const inline = /^allowed-tools:[ \t]*(.+)$/m.exec(body);
  if (inline) {
    return inline[1]
      .replace(/^\[|\]$/g, '')
      .split(',')
      .map((s) => s.trim().replace(/^["']|["']$/g, ''))
      .filter(Boolean);
  }
  const block = /^allowed-tools:[ \t]*\r?\n((?:[ \t]*-[ \t]*\S+\r?\n?)+)/m.exec(body);
  if (block) {
    return block[1]
      .split(/\r?\n/)
      .map((l) => l.replace(/^[ \t]*-[ \t]*/, '').trim())
      .filter(Boolean);
  }
  return null;
}

/** The SKILL.md body plus every markdown file the skill ships beside it. */
function skillDocuments(skillDir) {
  const docs = [];
  const walk = (dir) => {
    for (const entry of readdirSync(dir)) {
      const full = join(dir, entry);
      if (statSync(full).isDirectory()) walk(full);
      else if (entry.endsWith('.md')) docs.push(full);
    }
  };
  walk(skillDir);
  return docs;
}

/**
 * Strip fenced code blocks before matching.
 *
 * Without this a bash block containing `# Run \`x\`` would count as an
 * instruction. Inside a fence the text is a sample, which is exactly the
 * teaching-versus-instructing line this checker refuses to cross.
 */
function stripFences(text) {
  return text.replace(/^```[\s\S]*?^```/gm, '');
}

function auditSkill(skillDir) {
  const skillMd = join(skillDir, 'SKILL.md');
  if (!existsSync(skillMd)) return null;
  const declared = parseFrontmatter(readFileSync(skillMd, 'utf8'));
  // No list declared means nothing to disagree with. Not a subject.
  if (!declared || declared.length === 0) return null;

  const findings = [];
  for (const doc of skillDocuments(skillDir)) {
    const text = stripFences(readFileSync(doc, 'utf8'));
    for (const { tool, re, label, reject } of REQUIREMENTS) {
      const accepted = SATISFIES[tool] ?? [tool];
      if (accepted.some((t) => declared.includes(t))) continue;
      const hit = re.exec(text);
      if (!hit) continue;
      const backticked = /`[^`]+`/.exec(hit[0])?.[0] ?? '';
      if (reject && reject.test(backticked)) continue;
      findings.push({
        tool,
        label,
        file: relative(REPO_ROOT, doc),
        quote: hit[0].trim().slice(0, 100),
      });
    }
  }
  return findings.length ? { declared, findings } : null;
}

const skillDirs = readdirSync(SKILLS_ROOT)
  .map((n) => join(SKILLS_ROOT, n))
  .filter((p) => statSync(p).isDirectory());

const offenders = new Map();
for (const dir of skillDirs) {
  const result = auditSkill(dir);
  if (result) offenders.set(relative(SKILLS_ROOT, dir), result);
}

const baseline = existsSync(BASELINE_PATH)
  ? JSON.parse(readFileSync(BASELINE_PATH, 'utf8'))
  : { $comment: '', skills: [] };
const grandfathered = new Set(baseline.skills ?? []);

if (process.argv.includes('--report')) {
  for (const [name, { declared, findings }] of [...offenders].sort()) {
    console.log(`${name}  [${declared.join(', ')}]`);
    for (const f of findings) console.log(`    needs ${f.tool}: ${f.quote}  (${f.file})`);
  }
  console.log(`\n${offenders.size} skill(s) whose prose disagrees with their tool list`);
  process.exit(0);
}

const added = [...offenders.keys()].filter((n) => !grandfathered.has(n));
// A baseline entry that no longer offends must be deleted, or the list stops
// being a ratchet and becomes a permanent amnesty.
const stale = [...grandfathered].filter((n) => !offenders.has(n));

let failed = false;
if (added.length) {
  failed = true;
  console.error(`\n${added.length} skill(s) instruct a tool their allowed-tools omits:\n`);
  for (const name of added) {
    const { declared, findings } = offenders.get(name);
    console.error(`  ${name}  declares [${declared.join(', ')}]`);
    for (const f of findings) console.error(`    needs ${f.tool}: ${f.quote}\n      ${f.file}`);
  }
  console.error(
    '\nallowed-tools is a PRE-GRANT, not a ceiling: an omitted tool still runs, but it\n' +
      'prompts the user mid-procedure, and the Cursor host reads the same field as a hard\n' +
      'ceiling. Fix one of the two halves: LIST the tool if the skill really performs the\n' +
      'work, or reword the step as advice if the skill only teaches. Do NOT add it to the\n' +
      'baseline. See docs/skills-allowed-tools-direction.md for the per-skill call.\n',
  );
}
if (stale.length) {
  failed = true;
  console.error(`\n${stale.length} baseline entry(ies) no longer offend, delete them:\n`);
  for (const name of stale) console.error(`  ${name}`);
  console.error(`\n  ${relative(REPO_ROOT, BASELINE_PATH)}\n`);
}

if (failed) process.exit(1);
console.log(
  `allowed-tools check: ${offenders.size} known offender(s), 0 new, 0 stale (baseline ${grandfathered.size})`,
);
